import{_ as a,o as r,c as e,a2 as i}from"./chunks/framework.CHeM0PsO.js";const o="/images/agent-chat.webp",l="/images/agent-search.webp",n="/images/agent-models.webp",s="/images/agent-sessions.webp",b=JSON.parse('{"title":"聊天与会话","description":"","frontmatter":{},"headers":[],"relativePath":"guide/agent/chat.md","filePath":"guide/agent/chat.md","lastUpdated":1789295632000}'),d={name:"guide/agent/chat.md"};function g(h,t,p,c,u,m){return r(),e("div",null,[...t[0]||(t[0]=[i('<h1 id="聊天与会话" tabindex="-1">聊天与会话 <a class="header-anchor" href="#聊天与会话" aria-label="Permalink to &quot;聊天与会话&quot;">​</a></h1><p>进入会话后就可以和角色自由对话。会话页面顶部有一排功能标签页，每个标签页说明如下。</p><table tabindex="0"><thead><tr><th>标签页</th><th>作用</th></tr></thead><tbody><tr><td>消息</td><td>对话主界面</td></tr><tr><td>搜索</td><td>在当前会话中检索历史消息</td></tr><tr><td>模型</td><td>查看和切换本次对话使用的 AI 模型</td></tr><tr><td>生图</td><td>配置对话中自动插图</td></tr><tr><td>主动消息</td><td>让角色主动找你，详见<a href="/guide/agent/proactive">主动消息</a></td></tr><tr><td>记忆</td><td>让角色记住之前聊过的内容，详见<a href="/guide/agent/memory">记忆</a></td></tr><tr><td>世界书</td><td>查看角色的背景知识设定</td></tr><tr><td>对话风格</td><td>切换当前会话的对话风格</td></tr><tr><td>会话</td><td>重命名、删除、导入导出等会话级设置</td></tr></tbody></table><h2 id="消息" tabindex="-1">消息 <a class="header-anchor" href="#消息" aria-label="Permalink to &quot;消息&quot;">​</a></h2><p>你和角色的所有交流都在这里进行。</p><p><strong>发送消息</strong>：支持文字和图片。发送图片后角色会「看图」并回应（识图），你可以在图片菜单中查看「传给 AI 的识图内容」确认它看到了什么。注意智能体图片消息只支持图片，不支持视频等其他文件。</p><p><strong>输出形态</strong>：</p><ul><li><strong>分段输出</strong>：角色的较长回复会按段落拆成多个气泡逐段展示，更有节奏感（在「会话」中开关）。</li><li><strong>上下文边界</strong>：对话太长时，界面会出现一条分界线。线以上的更早消息<strong>不再原文进入模型</strong>——角色不是忘了，而是靠记忆或便签来回顾（见<a href="/guide/agent/memory">记忆</a>）。</li><li>消息按日期自动分隔；角色触发世界书条目时会提示本轮激活了哪些设定。</li></ul><p><strong>消息操作</strong>：每条消息都可以编辑、删除，或「回溯」——让对话回到这一条重新开始。对角色回复可以要求重新生成；发送过程中可以随时中止。</p><p><strong>表情</strong>：输入框的表情按钮可以插入全站自定义表情（<code>:名字:</code>）；如果角色配置了专属表情包，它会自己挑合适的时机发贴纸。语法详见<a href="/guide/agent/syntax">对话语法</a>。</p><p><img src="'+o+'" alt="智能体消息"></p><h2 id="搜索" tabindex="-1">搜索 <a class="header-anchor" href="#搜索" aria-label="Permalink to &quot;搜索&quot;">​</a></h2><p>在当前会话内按关键词检索所有历史消息，点击结果直接定位并高亮那条消息。</p><p><img src="'+l+'" alt="智能体搜索"></p><h2 id="模型" tabindex="-1">模型 <a class="header-anchor" href="#模型" aria-label="Permalink to &quot;模型&quot;">​</a></h2><p>为当前会话选择对话模型。每个模型以卡片展示：</p><ul><li><strong>上下文长度</strong>：一次能读进模型的内容量上限。</li><li><strong>输出上限</strong>：单次回复最多生成的量。</li><li><strong>费用</strong>：每次发送预计扣除的额度（卡片上会显示「预计单次发送费用」）。</li><li><strong>成功率（1 小时）</strong>：近期调用成功的比例，仅作参考。</li></ul><p>不同模型的效果、风格和费用不同，切换只影响当前会话。具体效果以个人体验为准。</p><p><img src="'+n+'" alt="模型选择"></p><h2 id="生图" tabindex="-1">生图 <a class="header-anchor" href="#生图" aria-label="Permalink to &quot;生图&quot;">​</a></h2><p>在「生图」页配置 AI 配图：</p><ul><li>选择生图模型（卡片展示每张费用和成功率），选「无」则关闭。</li><li>开启后，角色会在合适的时机根据对话内容生成插图。</li><li>设置了<strong>默认参考图</strong>的角色，在选择支持参考图的模型时会把参考图一起传给生图模型，让形象更稳定。</li><li>每轮自动生成的图片张数有上限，超出的图片指令需要手动点击生成。</li><li>生成的图片经过内容审核，不合规的会被拦截并提示原因；保存时如果遇到网盘空间不足、文件类型不允许或额度不足，也会有对应提示。</li></ul><h2 id="会话" tabindex="-1">会话 <a class="header-anchor" href="#会话" aria-label="Permalink to &quot;会话&quot;">​</a></h2><p>「会话」标签页管理当前会话：</p><ul><li><strong>重命名 / 删除</strong>会话；删除<strong>不可恢复</strong>，会一并删除本会话的私信记录、压缩便签以及绑定的云端记忆条目（仅模型调用流水保留），删除前会再次确认。</li><li><strong>导入 / 导出</strong>聊天记录备份（导入最多 10000 条）。</li><li><strong>分段输出</strong>开关。</li><li><strong>时间感知</strong>开关：把当前北京时间告诉角色，让它能理解「现在几点」。默认开启；<a href="/guide/agent/proactive">主动消息</a>依赖此功能。</li></ul><h2 id="回溯与多线" tabindex="-1">回溯与多线 <a class="header-anchor" href="#回溯与多线" aria-label="Permalink to &quot;回溯与多线&quot;">​</a></h2><ul><li>同一角色可以开多个会话，各自独立。</li><li>回溯会丢弃该消息之后的内容，适合试不同走向。</li></ul><p><img src="'+s+'" alt="智能体会话列表"></p><h2 id="对话中会遇到的状态" tabindex="-1">对话中会遇到的状态 <a class="header-anchor" href="#对话中会遇到的状态" aria-label="Permalink to &quot;对话中会遇到的状态&quot;">​</a></h2><ul><li><strong>角色被封禁 / 会话被封禁</strong>：管理员处置后无法继续发送消息或修改设置，但仍可查看历史记录（会话级封禁则连历史也看不到，可在删除前导出）。</li><li><strong>回复生成失败</strong>：一般标注了错误类型（超时 / 上游请求失败等），你发送的内容会退回输入框，直接重试即可；失败的那次不会计费。</li></ul>',30)])])}const f=a(d,[["render",g]]);export{b as __pageData,f as default};
